final_aql:
LET reviewsByUserAndMonth = (
    FOR u IN Users
        FILTER u.name == "Michelle"

        FOR r IN 1..1 OUTBOUND u WritesReview
            LET reviewMonth = r.month || "-" || r.year
            RETURN {user: u._id, business: r.business_id, month: reviewMonth}
)

LET results = (
    FOR m IN 1..1 OUTBOUND reviewsByUserAndMonth WritesReview
        GROUP BY m.month
        RETURN {month: _GROUP, count: COUNT(DISTINCT m.business)}
)

RETURN results

