original_aql:
FOR b IN Businesses
LET categoriesCount = (
    LENGTH(
        FOR c IN 1..INFINITY OUTBOUND b BusinessCategory
            RETURN 1
    )
)

SORT b._id DESC, categoriesCount DESC
LIMIT 1

RETURN {
    business_id: b.business_id,
    categories_count: categoriesCount
}

